import {connected,connectionRailStations} from './region.js?v=reward-progress-1';
import {streetGraph} from './highway.js?v=reward-progress-1';
const sectorBonus=(sector,land,airports,seaports)=>Math.min(15,land*3)+Math.min(40,airports*(sector==='commercial'?20:5)+seaports*(sector==='commercial'?8:20));
export function regionalMarketAccess(c){const N=c.tiles.length,street=streetGraph(c),roadsOpen=c.finance.roadCondition>20,gates=[];
 for(const con of c.region.connections){if(!['road','highway','rail'].includes(con.kind)||!connected(c,con))continue;if(con.kind==='rail'){const stations=connectionRailStations(c,con),groups=new Set(roadsOpen?stations.flatMap(t=>t.roadIds):[]);if(stations.length)gates.push({kind:'land',side:con.side,groups,stations});}else if(roadsOpen){const group=street.groups[con.tile+(con.kind==='highway'?N:0)];if(group>=0)gates.push({kind:'land',side:con.side,groups:new Set([group]),stations:[]});}}
 for(const p of c.stats.facilityPlots)if(p.operating){const groups=new Set(p.ids.flatMap(i=>c.tiles[i].roadIds));if(groups.size)gates.push({kind:p.type,groups,stations:[]});}
 const counts={commercial:0,industrial:0},served={commercial:0,industrial:0},total={commercial:0,industrial:0};
 for(const t of c.tiles){t.marketNeighbors=[];t.marketAirports=0;t.marketSeaports=0;t.marketDemandBonus=0;if(!['commercial','industrial'].includes(t.type)||t.rubble)continue;counts[t.type]++;const sides=new Set();for(const gate of gates){const reaches=(roadsOpen&&t.roadIds.some(id=>gate.groups.has(id)))||gate.stations.some(s=>Math.max(Math.abs(s.x-t.x),Math.abs(s.y-t.y))<=3);if(!reaches)continue;if(gate.kind==='land')sides.add(gate.side);else if(gate.kind==='airport')t.marketAirports++;else t.marketSeaports++;}t.marketNeighbors=[...sides].sort();t.marketDemandBonus=sectorBonus(t.type,sides.size,t.marketAirports,t.marketSeaports);total[t.type]+=t.marketDemandBonus;if(t.marketDemandBonus>0)served[t.type]++;}
 const potential=sector=>sectorBonus(sector,new Set(gates.filter(g=>g.kind==='land').map(g=>g.side)).size,gates.filter(g=>g.kind==='airport').length,gates.filter(g=>g.kind==='seaport').length);
 return{marketConnectedPlots:served,marketZonedPlots:counts,marketDemandBonus:Object.fromEntries(['commercial','industrial'].map(s=>[s,counts[s]?total[s]/counts[s]:potential(s)]))};
}
export function marketAccessDescription(t){if(!['commercial','industrial'].includes(t.type))return'';const paths=[...(t.marketNeighbors||[]).map(s=>s+' neighbor'),...(t.marketAirports?[t.marketAirports+' airport(s)']:[]),...(t.marketSeaports?[t.marketSeaports+' seaport(s)']:[])];return paths.length?`Outside markets: ${paths.join(', ')}. Local demand support: +${t.marketDemandBonus} points.`:'No reachable outside market. Connect this district to a paid border route, an active freight station, or an operating airport/seaport.';}
